import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline


_cpp_src = r"""
#include <torch/extension.h>
torch::Tensor conv_transpose3d_cuda(torch::Tensor x, torch::Tensor w, torch::Tensor bias,
                                    int64_t stride, int64_t padding, int64_t output_padding,
                                    int64_t dilation, int64_t groups);
"""

_cuda_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda_runtime.h>

constexpr int K = 3;
constexpr int K3 = 27;
constexpr int TILE = 6;
constexpr int IN_TILE = TILE + K - 1;   // 8
constexpr int C_CHUNK = 8;
constexpr int CO_TILE = 8;
constexpr int THREADS = TILE * TILE * TILE; // 216
constexpr int SX_FLOATS = C_CHUNK * IN_TILE * IN_TILE * IN_TILE; // 4096
constexpr int SW_FLOATS = K3 * C_CHUNK * CO_TILE;                // 1728

__global__ void conv_transpose3d_tiled_kernel(
    const float* __restrict__ x,
    const float* __restrict__ w,
    const float* __restrict__ bias,
    float* __restrict__ y,
    int B, int Ci, int Co,
    int Din, int Hin, int Win,
    int Dout, int Hout, int Wout,
    int tiles_z, int co_blocks,
    bool has_bias) {
    extern __shared__ float smem[];
    float* sX = smem;                  // [c][iz][iy][ix]
    float* sW = smem + SX_FLOATS;      // [k][c][co_local]

    const int tx = threadIdx.x;
    const int ty = threadIdx.y;
    const int tz = threadIdx.z;
    const int tid = tx + TILE * (ty + TILE * tz);

    const int ox0 = blockIdx.x * TILE;
    const int oy0 = blockIdx.y * TILE;
    const int bz  = blockIdx.z;

    const int co_blk = bz / (tiles_z * B);
    int rem = bz - co_blk * tiles_z * B;
    const int b = rem / tiles_z;
    const int sz = rem - b * tiles_z;
    const int oz0 = sz * TILE;
    const int co0 = co_blk * CO_TILE;

    const int gx = ox0 + tx;
    const int gy = oy0 + ty;
    const int gz = oz0 + tz;

    float acc[CO_TILE];
    #pragma unroll
    for (int i = 0; i < CO_TILE; ++i) acc[i] = 0.0f;

    const int ix0 = ox0 - (K - 1);
    const int iy0 = oy0 - (K - 1);
    const int iz0 = oz0 - (K - 1);

    for (int ci0 = 0; ci0 < Ci; ci0 += C_CHUNK) {
        // Load input halo tile for this channel chunk.
        for (int n = tid; n < SX_FLOATS; n += THREADS) {
            const int c = n >> 9;                 // /512
            const int r = n & 511;
            const int iz = r >> 6;                // /64
            const int iy = (r >> 3) & 7;
            const int ix = r & 7;

            const int gix = ix0 + ix;
            const int giy = iy0 + iy;
            const int giz = iz0 + iz;

            float v = 0.0f;
            if (gix >= 0 && gix < Win && giy >= 0 && giy < Hin && giz >= 0 && giz < Din) {
                const long long idx = (((long long)b * Ci + (ci0 + c)) * Din + giz) * Hin * Win
                                    + (long long)giy * Win + gix;
                v = x[idx];
            }
            sX[n] = v;
        }

        // Load packed-ish weights for this input-channel chunk and output-channel tile.
        for (int n = tid; n < SW_FLOATS; n += THREADS) {
            const int k = n >> 6;                 // /64
            const int r = n & 63;
            const int c = r >> 3;                 // /8
            const int cl = r & 7;
            const int ci = ci0 + c;
            const int co = co0 + cl;
            sW[n] = w[((long long)ci * Co + co) * K3 + k];
        }
        __syncthreads();

        #pragma unroll
        for (int kz = 0; kz < K; ++kz) {
            const int iz = tz + (K - 1) - kz;
            #pragma unroll
            for (int ky = 0; ky < K; ++ky) {
                const int iy = ty + (K - 1) - ky;
                #pragma unroll
                for (int kx = 0; kx < K; ++kx) {
                    const int ix = tx + (K - 1) - kx;
                    const int k = (kz * K + ky) * K + kx;
                    const int xoff = ((iz * IN_TILE + iy) * IN_TILE) + ix;
                    #pragma unroll
                    for (int c = 0; c < C_CHUNK; ++c) {
                        const float xv = sX[c * (IN_TILE * IN_TILE * IN_TILE) + xoff];
                        const int wbase = (k * C_CHUNK + c) * CO_TILE;
                        #pragma unroll
                        for (int cl = 0; cl < CO_TILE; ++cl) {
                            acc[cl] = fmaf(xv, sW[wbase + cl], acc[cl]);
                        }
                    }
                }
            }
        }
        __syncthreads();
    }

    if (gx < Wout && gy < Hout && gz < Dout) {
        #pragma unroll
        for (int cl = 0; cl < CO_TILE; ++cl) {
            const int co = co0 + cl;
            if (co < Co) {
                float v = acc[cl];
                if (has_bias) v += bias[co];
                const long long idx = (((long long)b * Co + co) * Dout + gz) * Hout * Wout
                                    + (long long)gy * Wout + gx;
                y[idx] = v;
            }
        }
    }
}

torch::Tensor conv_transpose3d_cuda(torch::Tensor x, torch::Tensor w, torch::Tensor bias,
                                    int64_t stride, int64_t padding, int64_t output_padding,
                                    int64_t dilation, int64_t groups) {
    TORCH_CHECK(x.is_cuda(), "input must be CUDA");
    TORCH_CHECK(w.is_cuda(), "weight must be CUDA");
    TORCH_CHECK(x.scalar_type() == at::kFloat, "input must be float32");
    TORCH_CHECK(w.scalar_type() == at::kFloat, "weight must be float32");
    TORCH_CHECK(x.dim() == 5, "input must be NCDHW");
    TORCH_CHECK(w.dim() == 5, "weight must be (Ci, Co, kD, kH, kW)");
    TORCH_CHECK(stride == 1 && padding == 0 && output_padding == 0 && dilation == 1 && groups == 1,
                "custom kernel supports stride=1, padding=0, output_padding=0, dilation=1, groups=1");
    TORCH_CHECK(w.size(2) == K && w.size(3) == K && w.size(4) == K, "custom kernel supports kernel_size=3");

    const int B   = (int)x.size(0);
    const int Ci  = (int)x.size(1);
    const int Din = (int)x.size(2);
    const int Hin = (int)x.size(3);
    const int Win = (int)x.size(4);

    TORCH_CHECK(w.size(0) == Ci, "weight/input channel mismatch");
    const int Co = (int)w.size(1);
    TORCH_CHECK(Ci % C_CHUNK == 0, "in_channels must be divisible by 8 for custom kernel");
    TORCH_CHECK(Co % CO_TILE == 0, "out_channels must be divisible by 8 for custom kernel");

    const int Dout = (Din - 1) * (int)stride - 2 * (int)padding + (int)dilation * (K - 1) + (int)output_padding + 1;
    const int Hout = (Hin - 1) * (int)stride - 2 * (int)padding + (int)dilation * (K - 1) + (int)output_padding + 1;
    const int Wout = (Win - 1) * (int)stride - 2 * (int)padding + (int)dilation * (K - 1) + (int)output_padding + 1;

    auto y = torch::empty({B, Co, Dout, Hout, Wout}, x.options());
    auto xc = x.contiguous();
    auto wc = w.contiguous();

    const bool has_bias = bias.numel() > 0;
    if (has_bias) {
        TORCH_CHECK(bias.is_cuda() && bias.scalar_type() == at::kFloat && bias.numel() == Co,
                    "bias must be CUDA float32 with numel == out_channels");
    }

    const int tiles_x = (Wout + TILE - 1) / TILE;
    const int tiles_y = (Hout + TILE - 1) / TILE;
    const int tiles_z = (Dout + TILE - 1) / TILE;
    const int co_blocks = Co / CO_TILE;
    const long long zblocks = (long long)tiles_z * B * co_blocks;
    TORCH_CHECK(zblocks <= 65535, "grid z dimension too large");

    dim3 block(TILE, TILE, TILE);
    dim3 grid((unsigned)tiles_x, (unsigned)tiles_y, (unsigned)zblocks);
    const size_t shmem = (size_t)(SX_FLOATS + SW_FLOATS) * sizeof(float);

    auto stream = at::cuda::getCurrentCUDAStream();
    conv_transpose3d_tiled_kernel<<<grid, block, shmem, stream>>>(
        xc.data_ptr<float>(),
        wc.data_ptr<float>(),
        has_bias ? bias.data_ptr<float>() : nullptr,
        y.data_ptr<float>(),
        B, Ci, Co,
        Din, Hin, Win,
        Dout, Hout, Wout,
        tiles_z, co_blocks,
        has_bias);

    return y;
}
"""

_ext = load_inline(
    name="conv_transpose3d_tiled_ext",
    cpp_sources=[_cpp_src],
    cuda_sources=[_cuda_src],
    functions=["conv_transpose3d_cuda"],
    extra_cuda_cflags=["-O3"],
    verbose=False,
)


def _triple(v):
    if isinstance(v, int):
        return (v, v, v)
    return tuple(v)


class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1,
                 padding: int = 0, output_padding: int = 0, dilation: int = 1,
                 groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        # Keep the standard module as the parameter/state_dict holder, but do not call it in forward.
        self.conv_transpose3d = nn.ConvTranspose3d(
            in_channels, out_channels, (kernel_size, kernel_size, kernel_size),
            stride=stride, padding=padding, output_padding=output_padding,
            dilation=dilation, groups=groups, bias=bias
        )

    def _use_custom(self, x: torch.Tensor) -> bool:
        c = self.conv_transpose3d
        return (
            x.is_cuda and
            x.dtype == torch.float32 and
            _triple(c.stride) == (1, 1, 1) and
            _triple(c.padding) == (0, 0, 0) and
            _triple(c.output_padding) == (0, 0, 0) and
            _triple(c.dilation) == (1, 1, 1) and
            c.groups == 1 and
            c.kernel_size == (3, 3, 3) and
            c.in_channels % 8 == 0 and
            c.out_channels % 8 == 0
        )

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        c = self.conv_transpose3d
        if self._use_custom(x):
            bias = c.bias if c.bias is not None else torch.empty(0, device=x.device, dtype=x.dtype)
            return _ext.conv_transpose3d_cuda(
                x.contiguous(), c.weight.contiguous(), bias.contiguous(),
                1, 0, 0, 1, 1
            )
        return F.conv_transpose3d(
            x, c.weight, c.bias, c.stride, c.padding, c.output_padding,
            c.groups, c.dilation
        )

